metadata.https://raw.githubusercontent.com/meanin:
format: meaning/draft-1
id: geo
name: Geography
description: >-
  Places with a meaning shared across datasets: countries, cities, and the
  people who live in them. Starter subset: the country list holds a starter
  set of countries; the full ISO 3166-1 list comes later.
license: CC0-1.0
concepts:
  - id: country
    kind: entity
    labels:
      en: Country
      ru: Страна
    synonyms:
      en: [nation, countries]
      ru: [государство, страны]
    description: >-
      A country or territory with an ISO 3166-1 code, identified independently
      of any data source. Values are keyed by the lowercase ISO 3166-1 alpha-2
      code. A dataset that stores a country by name matches it against a
      value's labels and aliases; one that stores a code matches it against
      the value's codes.
    values:
      - id: ar
        labels: {en: Argentina, ru: Аргентина}
        codes: {alpha2: AR, alpha3: ARG, numeric: "032"}
      - id: au
        labels: {en: Australia, ru: Австралия}
        codes: {alpha2: AU, alpha3: AUS, numeric: "036"}
      - id: at
        labels: {en: Austria, ru: Австрия}
        codes: {alpha2: AT, alpha3: AUT, numeric: "040"}
      - id: be
        labels: {en: Belgium, ru: Бельгия}
        codes: {alpha2: BE, alpha3: BEL, numeric: "056"}
      - id: br
        labels: {en: Brazil, ru: Бразилия}
        codes: {alpha2: BR, alpha3: BRA, numeric: "076"}
      - id: ca
        labels: {en: Canada, ru: Канада}
        codes: {alpha2: CA, alpha3: CAN, numeric: "124"}
      - id: cl
        labels: {en: Chile, ru: Чили}
        codes: {alpha2: CL, alpha3: CHL, numeric: "152"}
      - id: cz
        labels: {en: Czechia, ru: Чехия}
        aliases:
          en: [Czech Republic]
          ru: [Чешская Республика]
        codes: {alpha2: CZ, alpha3: CZE, numeric: "203"}
      - id: dk
        labels: {en: Denmark, ru: Дания}
        codes: {alpha2: DK, alpha3: DNK, numeric: "208"}
      - id: fi
        labels: {en: Finland, ru: Финляндия}
        codes: {alpha2: FI, alpha3: FIN, numeric: "246"}
      - id: fr
        labels: {en: France, ru: Франция}
        codes: {alpha2: FR, alpha3: FRA, numeric: "250"}
      - id: de
